export function formatCount(n) {
  return String(n);
}

export function formatMoney(cents, currency) {
  if (!Number.isInteger(cents) || cents < 0)
    throw new RangeError('cents must be a non-negative integer');
  const whole = String(Math.floor(cents / 100)).replace(
    /\B(?=(\d{3})+(?!\d))/g,
    ',',
  );
  return currency + ' ' + whole + '.' + String(cents % 100).padStart(2, '0');
}

import { formatMoney } from './format.js';

export function total(cart) {
  return cart.items.reduce(
    (sum, item) => sum + item.priceCents * item.quantity,
    0,
  );
}

export function summary(cart, currency) {
  return {
    items: cart.items.reduce((sum, item) => sum + item.quantity, 0),
    total: formatMoney(total(cart), currency),
  };
}

import { total } from './cart.js';
import { formatMoney } from './format.js';

export function report(carts, currency) {
  return carts
    .map(
      (cart) =>
        cart.id +
        ': ' +
        (currency === undefined
          ? total(cart)
          : formatMoney(total(cart), currency)),
    )
    .join('\n');
}
